use gtk4::prelude::*;

/// URLs are generated by Bridge; never pass through a command interpreter.
#[cfg(windows)]
fn launch(url: &str) -> anyhow::Result<()> {
    use windows_sys::Win32::{
        System::Com::{CoInitializeEx, CoUninitialize, COINIT_APARTMENTTHREADED},
        UI::{Shell::ShellExecuteW, WindowsAndMessaging::SW_SHOWNORMAL},
    };
    anyhow::ensure!(!url.contains('\0'), "Invalid URL");
    let url: Vec<u16> = url.encode_utf16().chain(Some(0)).collect();
    let verb: Vec<u16> = "open".encode_utf16().chain(Some(0)).collect();
    // GTK may already own the thread's COM apartment. Balance only our successful init.
    let initialized = unsafe { CoInitializeEx(std::ptr::null(), COINIT_APARTMENTTHREADED as u32) };
    const RPC_E_CHANGED_MODE: i32 = 0x80010106_u32 as i32;
    anyhow::ensure!(
        initialized >= 0 || initialized == RPC_E_CHANGED_MODE,
        "COM initialization failed: {initialized:#x}"
    );
    let result = unsafe {
        ShellExecuteW(
            std::ptr::null_mut(),
            verb.as_ptr(),
            url.as_ptr(),
            std::ptr::null(),
            std::ptr::null(),
            SW_SHOWNORMAL,
        ) as isize
    };
    if initialized >= 0 {
        unsafe { CoUninitialize() };
    }
    anyhow::ensure!(result > 32, "Windows browser launch failed (code {result})");
    Ok(())
}

#[cfg(not(windows))]
fn launch(url: &str) -> anyhow::Result<()> {
    gtk4::gio::AppInfo::launch_default_for_uri(url, None::<&gtk4::gio::AppLaunchContext>)?;
    Ok(())
}

pub fn open(parent: &impl IsA<gtk4::Window>, url: &str, fr: bool) {
    if let Err(error) = launch(url) {
        let dialog = gtk4::MessageDialog::builder()
            .transient_for(parent)
            .modal(true)
            .message_type(gtk4::MessageType::Error)
            .text(super::tr(fr, "Impossible d’ouvrir le navigateur", "Cannot open the browser"))
            .secondary_text(format!("{}\n\n{error}\n\n{url}", super::tr(fr,
                "Copiez le lien et collez-le dans votre navigateur. Vérifiez aussi le navigateur par défaut du système.",
                "Copy the link and paste it into your browser. Also check your default browser settings.")))
            .build();
        dialog.add_button(
            super::tr(fr, "Copier le lien", "Copy link"),
            gtk4::ResponseType::Accept,
        );
        dialog.add_button(super::tr(fr, "Fermer", "Close"), gtk4::ResponseType::Close);
        let url = url.to_owned();
        dialog.connect_response(move |dialog, response| {
            if response == gtk4::ResponseType::Accept {
                dialog.clipboard().set_text(&url);
            }
            dialog.close();
        });
        dialog.present();
    }
}
